--- 与选择器任务类似，ParallelSelector任务一旦有子任务返回成功，就会返回成功。
--- 不同的是，并行任务将同时运行其所有的子任务，而不是一次运行每个任务。
--- 如果一个任务返回成功，并行选择器任务将结束所有的子任务并返回成功。
--- 如果每个子任务都返回失败，那么ParallelSelector任务将返回失败。

------------ import ------------
local Composite = import("Frame.AI.BT.Composites.Composite")
------------ import ------------

------------ define ------------

------------ define ------------

---@class ParallelSelector
local ParallelSelector = Class("ParallelSelector", Composite)

function ParallelSelector:__init()
    Composite.__init(self)
end

function ParallelSelector:__delete()

end

function ParallelSelector:Update(context)
    local didAllFail = true
    ---@type BT.Composite[]
    local children = self._children
    for i, child in ipairs(children) do
        child:Tick(context)

        ---如果有子节点成功了，我们就返回成功
        if child.status == Composite.TaskStatus.Success then
            return Composite.TaskStatus.Success

        end
        
        --- 如果所有的子节点没有失败，我们还没有完成
        if child.status ~= Composite.TaskStatus.Failure then
            didAllFail = false
            
        end

    end

    if didAllFail then
        return Composite.TaskStatus.Failure
    end
    
    return Composite.TaskStatus.Running
end


return ParallelSelector
 